import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"在线聊天","description":"","frontmatter":{},"headers":[],"relativePath":"backend/chat.md","filePath":"backend/chat.md","lastUpdated":1794049926000}`),a={name:`backend/chat.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="在线聊天" tabindex="-1">在线聊天 <a class="header-anchor" href="#在线聊天" aria-label="Permalink to “在线聊天”">​</a></h1><p>本页说明在线聊天的会话与消息规则、推送、附件、部门群同步、聊天审计、策略参数与保留清理，适用于后端与前端开发者。</p><p>Chat 是 Tier 3 的可选模块：单聊、群聊、部门群与 AI 助手会话，消息的发送、撤回、编辑、回应、置顶、转发、已读与提及，聊天 Hub 与聊天审计。</p><h2 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to “数据”">​</a></h2><p>四张租户库表（<code>TenantScoped*</code>），平台一侧以 <code>platform</code> 为租户落在同一张表里，平台账号之间同样能聊天；独立库的租户在自己的库里。</p><table tabindex="0"><thead><tr><th>表</th><th>说明</th></tr></thead><tbody><tr><td><code>sys_chat_conversation</code></td><td>会话：类型（单聊、群聊、部门群、助手）、名称、头像、单聊唯一键、部门、群主、助手、成员数、最大消息序号、最后消息、公告、描述；软删除，不进差异日志</td></tr><tr><td><code>sys_chat_conversation_member</code></td><td>成员：角色（群主、管理员、成员）、未读数、已读到的消息与序号、免打扰、置顶、禁言、入会时间；退群与移出即软删除</td></tr><tr><td><code>sys_chat_message</code></td><td>消息：会话内序号、发送人与名字快照、类型、正文、附件（JSON）、撤回、编辑、回复快照、提及、置顶；不软删除，按保留期物理删除</td></tr><tr><td><code>sys_chat_message_reaction</code></td><td>表情回应：同一消息、同一用户、同一表情只有一条</td></tr></tbody></table><p>会话内的消息按序号排序：发消息时对会话行加一取得序号（行锁让同一会话的发送串行），历史的游标、已读位与已读回执都比序号。主键是 GUIDv7，同一毫秒内没有先后，不能用来排序。</p><h2 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to “规则”">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>单聊</td><td>同一对用户每侧只有一个，没有即建；不能和自己单聊</td></tr><tr><td>群聊</td><td>含群主至少两人，发起人为群主；加人、移出、改信息与公告、禁言要群主或管理员，转让群主与设管理员只有群主；群主不能退群或被移出；没有解散</td></tr><tr><td>部门群</td><td>只有本部门的成员能进，打开时补齐部门现有成员；没有群主与管理员，所以没人能改信息、置顶消息或禁言；名称随部门、不能改；平台没有部门，部门群只在租户一侧</td></tr><tr><td>成员范围</td><td>加进会话的人必须属于当前一侧：平台是注册在平台的账号，租户是注册在本租户的用户与租户成员（<code>CHAT_VALIDATION_021</code>）</td></tr><tr><td>发送</td><td>只有成员、没被禁言；文本必填不超过 4000 个字符，图片与文件至少一个附件（可带说明），语音恰好一个附件、1 到 60 秒、没有正文；系统提示与助手回复只由服务端追加</td></tr><tr><td>提及与回复</td><td>最多提及 20 名成员；只能回复本会话未撤回的消息，存「发送人: 内容」快照</td></tr><tr><td>撤回</td><td>本人、发出 2 分钟内，清空正文、保留行与附件</td></tr><tr><td>编辑</td><td>本人的文本、发出 5 分钟内、没被禁言</td></tr><tr><td>置顶消息</td><td>单聊双方都能，群与部门群只有群主与管理员，每会话最多 10 条（<code>CHAT_CONFLICT_001</code>）</td></tr><tr><td>转发</td><td>服务端单条转发到一个或多个会话，原样复制类型、正文与附件，不带转发来源，助手回复按文本转出；系统提示与已撤回的不能转发，不是成员或被禁言的会话逐项失败</td></tr><tr><td>已读</td><td>未读清零、已读位前移（不回退，没给消息即读到最新），已读位推给全体成员</td></tr></tbody></table><p>系统提示（建群、邀请、退群、移出、转让）与会话预览按发起调用的区域写进库里，公告以操作人的身份进消息流。</p><h2 id="助手会话" tabindex="-1">助手会话 <a class="header-anchor" href="#助手会话" aria-label="Permalink to “助手会话”">​</a></h2><p>一个用户对一个助手只有一个会话，打开时没有即建并发开场白。助手不是成员，不算未读，助手会话也不显示已读回执。回复是前端发出用户消息之后单独发起的调用：</p><ol><li>前端发出提问，再调 <code>chat-messages.reply-assistant</code>，带自己生成的 <code>replyId</code>。</li><li>服务端从库里取最近的提问与回复，经 Contracts 的 <code>IChatAssistants</code> 流式生成。Chat 不引用 AI，AI 关掉时没有实现，三个助手操作（<code>chat-conversations.assistants</code>、<code>open-assistant</code>、<code>chat-messages.reply-assistant</code>）返回 503 <code>CHAT_UNAVAILABLE_001</code>，聊天其余功能照常。</li><li>生成期间这次调用还没开事务，增量经立即推送发给本人（<code>ChatAssistantDelta</code>）。</li><li>结束后过敏感词（与用户输入同一套），落库为一条助手消息（超过 20000 个字符截断），提交之后按普通消息推送，再推 <code>ChatAssistantCompleted</code>。</li></ol><p>失败（模型不可达、空输出、敏感词、提示词停用、检索失败）时不留消息，操作以 Problem Details 结束，同时立即推 <code>ChatAssistantCompleted</code> 带 <code>errorCode</code> 与 <code>error</code>。</p><table tabindex="0"><thead><tr><th>错误码</th><th>说明</th></tr></thead><tbody><tr><td><code>CHAT_VALIDATION_026</code></td><td>不是助手会话</td></tr><tr><td><code>CHAT_VALIDATION_027</code></td><td>会话里没有可回答的提问</td></tr><tr><td><code>CHAT_UNAVAILABLE_001</code></td><td>助手不可用（AI 没有装配）</td></tr><tr><td><code>CHAT_UNAVAILABLE_002</code></td><td>生成失败。原因只有异常类型，完整异常看应用日志</td></tr><tr><td><code>CHAT_UNAVAILABLE_003</code></td><td>模型没有产生任何内容</td></tr></tbody></table><p>助手本身的配置见 <a href="./ai#助手">AI 能力</a>。</p><h2 id="操作与权限" tabindex="-1">操作与权限 <a class="header-anchor" href="#操作与权限" aria-label="Permalink to “操作与权限”">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>操作</th></tr></thead><tbody><tr><td><code>chat-conversations</code></td><td><code>mine</code>、<code>members</code>、<code>read-positions</code>、<code>department-tree</code>、<code>user-options</code>、<code>assistants</code>（只读）；<code>open-single</code>、<code>open-assistant</code>、<code>create-group</code>、<code>open-department</code>、<code>add-members</code>、<code>remove-members</code>、<code>leave</code>、<code>update-info</code>、<code>transfer-owner</code>、<code>silence-members</code>、<code>set-member-role</code>、<code>pin</code>、<code>mute</code>、<code>mark-read</code></td></tr><tr><td><code>chat-messages</code></td><td><code>history</code>、<code>search</code>、<code>pinned</code>、<code>presign</code>（只读）；<code>send</code>、<code>recall</code>、<code>edit</code>、<code>react</code>、<code>pin</code>、<code>unpin</code>、<code>forward</code>、<code>fast-upload</code>、<code>reply-assistant</code></td></tr><tr><td><code>chat-audit</code></td><td><code>list</code>、<code>get</code>、<code>members</code></td></tr></tbody></table><p>普通端点 <code>POST /api/chat-messages/attachments</code> 上传附件（multipart 字段 <code>file</code>，要 <code>chat.chat-messages.send</code>，访问日志记作 <code>chat-messages.upload</code>）。</p><table tabindex="0"><thead><tr><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>chat.chat-conversations.read</code></td><td>查看与参与会话（打开、退群、置顶、免打扰、已读也用它）</td></tr><tr><td><code>chat.chat-messages.read</code></td><td>查看历史、搜索、置顶消息与换附件地址</td></tr><tr><td><code>chat.chat-messages.send</code></td><td>发送、撤回、编辑、回应、置顶消息、转发与上传附件（进操作日志）</td></tr><tr><td><code>chat.chat-conversations.manage</code></td><td>建群与群治理（进操作日志）</td></tr><tr><td><code>chat.chat-audit.read</code></td><td>聊天审计</td></tr></tbody></table><p>权限码两侧都有。页面 <code>chat.conversations</code>（<code>/chat/conversations</code>）与 <code>chat.audit</code>（<code>/chat/audit</code>）在「消息中心」目录下。</p><h2 id="推送" tabindex="-1">推送 <a class="header-anchor" href="#推送" aria-label="Permalink to “推送”">​</a></h2><p>聊天 Hub <code>/hubs/chat</code> 由 Chat 登记、宿主一并映射，认证、会话门禁与连接登记同通知 Hub（见<a href="./realtime">实时推送</a>）。推送按成员点发给会话这一侧的用户，在调用提交之后发出；配了 Redis 时跨实例。</p><table tabindex="0"><thead><tr><th>方向</th><th>方法</th></tr></thead><tbody><tr><td>服务端推送</td><td><code>ReceiveChatMessage</code>、<code>ChatMessageRecalled</code>、<code>ChatConversationChanged</code>（11 种变更）、<code>ChatTyping</code>、<code>ChatMessageEdited</code>、<code>ChatReactionChanged</code>、<code>ChatReadPositionChanged</code>、<code>ChatAssistantDelta</code>、<code>ChatAssistantCompleted</code></td></tr><tr><td>客户端可调</td><td><code>JoinConversation</code>（核对成员后加入会话组）、<code>LeaveConversation</code>、<code>Typing</code>（核对成员后组播给组里的其他连接，不落库）</td></tr></tbody></table><p><code>ChatConversationChanged</code> 的变更种类：<code>created</code>、<code>member-added</code>、<code>member-removed</code>、<code>info-changed</code>、<code>owner-transferred</code>、<code>member-silenced</code>、<code>member-role-changed</code>、<code>pinned-changed</code>、<code>member-setting-changed</code>、<code>department-joined</code>、<code>department-kicked</code>。</p><h2 id="附件" tabindex="-1">附件 <a class="header-anchor" href="#附件" aria-label="Permalink to “附件”">​</a></h2><p>附件以会话为访问范围，经 Files 的附件契约 <code>IAttachmentFiles</code> 存取：上传与秒传只要聊天的发送权限，文件存在调用方这一侧、来源记 <code>chat</code>，大小上限与存储配额同普通上传；发送时核对附件是自己在聊天里上传的（<code>CHAT_DENIED_009</code>），文件名与大小以文件记录为准；会话成员经 <code>chat-messages.presign</code> 凭会话换签名地址，附件须出现在这个会话的消息里，或是自己上传、还没发出的文件。文件管理照旧要 <code>files.files.read</code>。保留清理不删附件文件。</p><p>群头像是文件主键或直链：给文件主键时同样须是自己在聊天里上传的（<code>CHAT_DENIED_009</code>），设上之后会话成员经 <code>chat-messages.presign</code> 凭会话换它的地址。单聊的头像是对端用户的头像。</p><h2 id="部门群同步" tabindex="-1">部门群同步 <a class="header-anchor" href="#部门群同步" aria-label="Permalink to “部门群同步”">​</a></h2><p>Organization 在加入与移出部门时记领域事件 <code>basicapp.organization.membership-changed</code>（随写入进发件箱），Chat 订阅它：已经建了的部门群里，进了部门即入群、移出部门即出群，并推会话变更（被移出的人也收到）。处理时按当时的归属核对，消息乱序或重复投递都只做一次；写库失败即投递失败、由消息代理重试。</p><h2 id="聊天审计" tabindex="-1">聊天审计 <a class="header-anchor" href="#聊天审计" aria-label="Permalink to “聊天审计”">​</a></h2><p>持 <code>chat.chat-audit.read</code> 即看当前一侧全部会话的消息，不要求是成员：</p><ul><li>列表按关键字（正文、发送人名、附件）与会话、发送人、消息类型、发送时间、是否撤回筛选，缺省不含已撤回的，筛选 <code>includeRecalled</code> 为 <code>true</code> 即都看；</li><li>消息详情带所在会话、附件、提及、回复与表情回应；</li><li>会话成员列出会话与它现在的成员。</li></ul><p>撤回清空的正文与编辑前的正文不另留。</p><h2 id="策略与保留清理" tabindex="-1">策略与保留清理 <a class="header-anchor" href="#策略与保留清理" aria-label="Permalink to “策略与保留清理”">​</a></h2><p>参数 <code>chat.policy</code>（JSON，类型选 Json），没建即用缺省值：</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;retentionDays&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">365</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sensitiveWords&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>retentionDays</code></td><td>消息保留天数，1 到 3650，只读平台的值</td></tr><tr><td><code>sensitiveWords</code></td><td>敏感词，不区分大小写的包含匹配；租户建了同键参数即用租户的；管发送与编辑的正文（含图片与文件的说明），不管群名、公告与文件名（<code>CHAT_VALIDATION_023</code>）</td></tr></tbody></table><p>JSON 不合法或保留天数越界即 <code>CHAT_VALIDATION_024</code>，发送与清理都不按错误的值执行。</p><p>内建作业 <code>chat.messages.cleanup</code> 每天 04:00（UTC）按平台与每个租户逐个清理（独立库的租户清它自己的库）：先删所属消息已过期的表情回应，再删过期的消息；不删会话、成员与附件文件。一侧失败只记日志，不影响其他侧。</p><h2 id="开关" tabindex="-1">开关 <a class="header-anchor" href="#开关" aria-label="Permalink to “开关”">​</a></h2><p><code>BasicApp:Modules:Chat:Enabled</code>（缺省开）。关掉后宿主不装配 Chat：权限目录、页面、Hub、附件上传端点与部门归属订阅都不在，菜单不下发、操作 404；Organization 照常发出领域事件，没有订阅方。四张表仍由正式库的基线脚本建出（开发库的 <code>InitTables</code> 只建装配了的包的表）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./realtime">实时推送</a> · <a href="./file">文件与存储</a> · <a href="./organization">组织架构</a> · <a href="./messaging">消息通知</a></li></ul>`,44)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};